const fs = require("fs");
const { JSDOM } = require("jsdom");

const html = fs.readFileSync("/tmp/page.html", "utf8");

function mkTicket(id, desc, name, created){
  return {id, description:desc, contactName:name, contactInfo:"010", source:"电话",
    category:"账号", priority:"高", attachmentNote:"", orderNumber:"", status:"待处理",
    assignee:"未分派", createdAt:created, updatedAt:created, assignments:null};
}
let serverA = mkTicket("TKT-000001","无法登录","张三","2026-10-03T10:00:00.000000000+08:00");
let serverB = mkTicket("TKT-000002","订单未到账","李四","2026-10-03T11:00:00.000000000+08:00");

let pendingAssigns = []; // 挂起的分派请求，由测试手动决定何时返回

const dom = new JSDOM(html, {
  url: "http://localhost/",
  runScripts: "dangerously",
  beforeParse(window){
    window.HTMLElement.prototype.scrollIntoView = function(){};
    window.fetch = function(url, opts){
      opts = opts || {};
      if (String(url).indexOf("/assignment") !== -1) {
        return new Promise((resolve, reject) => {
          pendingAssigns.push({url:String(url), body:JSON.parse(opts.body), resolve, reject});
        });
      }
      if (String(url) === "/api/tickets") {
        return Promise.resolve({status:200, ok:true,
          json:() => Promise.resolve({tickets:[serverB, serverA]})});
      }
      return Promise.reject(new Error("unexpected fetch " + url));
    };
  }
});
const window = dom.window;
const document = window.document;
const tick = () => new Promise(r => setTimeout(r, 0));
const settle = () => tick().then(tick).then(tick);

let failures = 0;
function check(name, cond, extra){
  if (cond) console.log("PASS " + name);
  else { failures++; console.log("FAIL " + name + (extra ? " -- " + extra : "")); }
}
function detailOpen(){ return document.getElementById("detail").classList.contains("open"); }
function detailText(){ return document.getElementById("detail").textContent; }
function assignNotice(){ return document.getElementById("assign-notice").textContent; }
function assignBtn(){ return document.getElementById("assign-btn"); }
function assignInput(){ return document.getElementById("f-assignee"); }
function viewButtonFor(id){
  for (const tr of document.querySelectorAll("#list-area tbody tr"))
    if (tr.children[0].textContent === id) return tr.querySelector("button[data-i]");
  return null;
}
function listRowText(id){
  for (const tr of document.querySelectorAll("#list-area tbody tr"))
    if (tr.children[0].textContent === id) return tr.textContent;
  return "";
}
function submitAssign(name){
  assignInput().value = name;
  document.getElementById("assign-form")
    .dispatchEvent(new window.Event("submit", {cancelable:true, bubbles:true}));
}
function resolveAssign(i, status, data){
  pendingAssigns[i].resolve({status, ok:status>=200&&status<300,
    json:() => Promise.resolve(data)});
}
function assignOk(t, changed){ return {ticket:t, changed}; }

(async function main(){
  await settle();
  check("列表渲染两条", document.querySelectorAll("#list-area tbody tr").length === 2);

  // 1) 打开 A 提交分派（挂起），随后打开 B
  viewButtonFor("TKT-000001").click();
  await settle();
  submitAssign("王五");
  await settle();
  check("A 提交后按钮等待中", assignBtn().disabled === true);
  check("请求发往 A", pendingAssigns.length === 1 &&
    pendingAssigns[0].url.indexOf("TKT-000001") !== -1);

  viewButtonFor("TKT-000002").click();
  await settle();
  check("详情切换到 B", detailText().indexOf("TKT-000002") !== -1);
  check("B 的按钮未被 A 占用", assignBtn().disabled === false);
  assignInput().value = "孙七"; // 在 B 中填写但未提交

  // 2) A 的成功结果迟到：不得影响 B 的详情
  serverA = Object.assign({}, serverA, {assignee:"王五",
    updatedAt:"2026-10-03T12:00:00.000000000+08:00",
    assignments:[{from:"未分派",to:"王五",at:"2026-10-03T12:00:00.000000000+08:00"}]});
  resolveAssign(0, 200, assignOk(serverA, true));
  await settle();
  check("详情仍显示 B", detailText().indexOf("TKT-000002") !== -1 &&
    detailText().indexOf("TKT-000001") === -1);
  check("B 的输入未被清空", assignInput().value === "孙七");
  check("B 无成功提示", assignNotice() === "");
  check("B 的按钮可用", assignBtn().disabled === false &&
    assignBtn().textContent === "提交分派");
  check("列表 A 负责人已更新", listRowText("TKT-000001").indexOf("王五") !== -1);
  check("列表 A 处理时间已更新", listRowText("TKT-000001").indexOf("12:00") !== -1);
  check("列表 B 仍未分派", listRowText("TKT-000002").indexOf("未分派") !== -1);

  // 3) B 提交（挂起），切回 A；B 的 409 迟到：不得出现在 A
  submitAssign("孙七");
  await settle();
  check("B 提交后按钮等待中", assignBtn().disabled === true);
  viewButtonFor("TKT-000001").click();
  await settle();
  check("A 详情显示最新负责人", detailText().indexOf("王五") !== -1);
  check("A 详情显示分派记录", detailText().indexOf("未分派 → 王五") !== -1);
  resolveAssign(1, 409, {error:"operation id was already used with a different assignee"});
  await settle();
  check("B 的 409 未出现在 A", assignNotice() === "");
  check("A 的按钮未被 B 的结果解除", assignBtn().disabled === false);

  // 4) A 提交后仅关闭详情：结果到达后详情保持关闭，重开显示最新结果
  submitAssign("赵六");
  await settle();
  document.querySelector("#detail .close").click();
  await settle();
  serverA = Object.assign({}, serverA, {assignee:"赵六",
    updatedAt:"2026-10-03T13:00:00.000000000+08:00",
    assignments: serverA.assignments.concat([{from:"王五",to:"赵六",at:"2026-10-03T13:00:00.000000000+08:00"}])});
  resolveAssign(2, 200, assignOk(serverA, true));
  await settle();
  check("结果到达后详情保持关闭", !detailOpen());
  check("列表 A 负责人更新为赵六", listRowText("TKT-000001").indexOf("赵六") !== -1);
  viewButtonFor("TKT-000001").click();
  await settle();
  check("重开 A 显示赵六", detailText().indexOf("赵六") !== -1);
  check("重开 A 显示两条分派记录",
    document.querySelectorAll("#detail .assign-list li").length === 2);

  // 5) 失败结果在停留在提交工单时正常显示，填写内容保留
  submitAssign("钱八");
  await settle();
  resolveAssign(3, 400, {error:"invalid assignee"});
  await settle();
  check("A 的 400 提示显示在 A", assignNotice().indexOf("输入错误") !== -1);
  check("A 的填写内容保留", assignInput().value === "钱八");
  check("A 的按钮恢复可用", assignBtn().disabled === false);

  // 6) 请求等待期间关闭并重开同一工单：按钮保持等待状态，结果到达后正常落地
  submitAssign("周九");
  await settle();
  document.querySelector("#detail .close").click();
  await settle();
  viewButtonFor("TKT-000001").click();
  await settle();
  check("重开 A 按钮仍在等待", assignBtn().disabled === true &&
    assignBtn().textContent === "正在分派…");
  serverA = Object.assign({}, serverA, {assignee:"周九",
    updatedAt:"2026-10-03T15:00:00.000000000+08:00",
    assignments: serverA.assignments.concat([{from:"赵六",to:"周九",at:"2026-10-03T15:00:00.000000000+08:00"}])});
  resolveAssign(4, 200, assignOk(serverA, true));
  await settle();
  check("结果到达后详情更新为周九", detailText().indexOf("周九") !== -1);
  check("成功提示显示", assignNotice().indexOf("分派成功") !== -1);
  check("输入已清空", assignInput().value === "");
  check("按钮恢复可用", assignBtn().disabled === false);

  // 7) 网络失败（连接问题）在停留在提交工单时提示
  submitAssign("吴十");
  await settle();
  pendingAssigns[5].reject(new Error("network down"));
  await settle();
  check("连接失败提示显示", assignNotice().indexOf("无法连接服务") !== -1);
  check("填写内容保留供重试", assignInput().value === "吴十");
  check("按钮恢复可用", assignBtn().disabled === false);

  console.log(failures === 0 ? "ALL PASS" : failures + " FAILURES");
  process.exit(failures === 0 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(1); });

