function listRowText(id){
  const rows = document.querySelectorAll("#list-area tbody tr");
  for (const tr of rows) if (tr.children[0].textContent === id) return tr.textContent;
  return "";
}
function submitAssign(name){
  document.getElementById("f-assignee").value = name;
  document.getElementById("assign-form")
    .dispatchEvent(new window.Event("submit", {cancelable:true, bubbles:true}));
}

(async function main(){
  await tick(); await tick(); // 等列表加载
  check("列表渲染两条", document.querySelectorAll("#list-area tbody tr").length === 2);

  // 打开 A 并提交分派（请求挂起）
  viewButtonFor("TKT-000001").click();
  await tick();
  check("详情显示 A", detailText().indexOf("TKT-000001") !== -1);
  submitAssign("王五");
  await tick();
  check("A 提交后按钮等待中", document.getElementById("assign-btn").disabled === true);
  check("A 的分派请求已发出", pendingAssigns.length === 1 &&
    pendingAssigns[0].url.indexOf("TKT-000001") !== -1 &&
    pendingAssigns[0].body.assignee === "王五");

  // 结果未返回时打开 B，并在 B 中填写负责人
  viewButtonFor("TKT-000002").click();
  await tick();
  check("详情切换到 B", detailText().indexOf("TKT-000002") !== -1);
  check("B 的按钮未被 A 的请求占用", document.getElementById("assign-btn").disabled === false);
  document.getElementById("f-assignee").value = "孙七";

  // A 的成功结果迟到
  serverA = Object.assign({}, serverA, {assignee:"王五",
    updatedAt:"2026-10-03T12:00:00.000000000+08:00",
    assignments:[{from:"未分派",to:"王五",at:"2026-10-03T12:00:00.000000000+08:00"}]});
  pendingAssigns[0].resolve({status:200, ok:true,
    json:() => Promise.resolve({ticket: serverA, changed:true})});
  await tick(); await tick();

  check("详情仍显示 B 的编号", detailText().indexOf("TKT-000002") !== -1 &&
    detailText().indexOf("TKT-000001") === -1);
  check("B 的输入未被清空", document.getElementById("f-assignee").value === "孙七");
  check("B 无成功提示", assignNotice() === "");
  check("B 的按钮恢复可用且文案正确",
    document.getElementById("assign-btn").disabled === false &&
    document.getElementById("assign-btn").textContent === "提交分派");
  check("列表中 A 的负责人已更新", listRowText("TKT-000001").indexOf("王五") !== -1);
  check("列表中 A 的处理时间已更新", listRowText("TKT-000001").indexOf("12:00") !== -1);
  check("列表中 B 仍未分派", listRowText("TKT-000002").indexOf("未分派") !== -1);

  // B 提交分派（挂起），切回 A；B 的失败结果迟到
  submitAssign("孙七");
  await tick();
  check("B 提交后按钮等待中", document.getElementById("assign-btn").disabled === true);
  viewButtonFor("TKT-000001").click();
  await tick();
  check("详情切回 A 显示最新负责人", detailText().indexOf("王五") !== -1);
  check("A 详情显示分派记录", detailText().indexOf("未分派 → 王五") !== -1);
  pendingAssigns[1].resolve({status:409, ok:false,
    json:() => Promise.resolve({error:"operation id was already used with a different assignee"})});
  await tick(); await tick();
  check("B 的 409 提示未出现在 A 的详情", assignNotice() === "");
  check("A 的按钮未被 B 的结果影响", document.getElementById("assign-btn").disabled === false);

  // A 再次提交（挂起）后只关闭详情；结果到达后详情保持关闭
  submitAssign("赵六");
  await tick();
  document.querySelector("#detail .close").click();
  await tick();
  check("详情已关闭", !document.getElementById("detail").classList.contains("open"));
  serverA = Object.assign({}, serverA, {assignee:"赵六",
    updatedAt:"2026-10-03T13:00:00.000000000+08:00",
    assignments: serverA.assignments.concat([{from:"王五",to:"赵六",at:"2026-10-03T13:00:00.000000000+08:00"}])});
  pendingAssigns[2].resolve({status:200, ok:true,
    json:() => Promise.resolve({ticket: serverA, changed:true})});
  await tick(); await tick();
  check("结果到达后详情保持关闭", !document.getElementById("detail").classList.contains("open"));
  check("列表中 A 负责人更新为赵六", listRowText("TKT-000001").indexOf("赵六") !== -1);

  // 重新打开 A：显示已知最新结果
  viewButtonFor("TKT-000001").click();
  await tick();
  check("重开 A 显示赵六", detailText().indexOf("赵六") !== -1);
  check("重开 A 显示两条分派记录",
    document.querySelectorAll("#detail .assign-list li").length === 2);

  // B 仍在等待：重开 B 应恢复等待中的按钮状态
  viewButtonFor("TKT-000002").click();
  await tick();
  check("重开 B 按钮仍在等待分派结果",
    document.getElementById("assign-btn").disabled === true &&
    document.getElementById("assign-btn").textContent === "正在分派…");
  // B 的请求最终成功，且用户正在看 B：提示与详情正常更新
  serverB = Object.assign({}, serverB, {assignee:"孙七",
    updatedAt:"2026-10-03T14:00:00.000000000+08:00",
    assignments:[{from:"未分派",to:"孙七",at:"2026-10-03T14:00:00.000000000+08:00"}]});
  pendingAssigns[1] = pendingAssigns[1]; // 已解决
  // 注意：B 的第二次提交是 pendingAssigns[1]（409 的那次已解决），这里重新提交一次
  // 实际上 B 只有过一次提交（index 1，已按 409 解决）。重新打开后按钮应为可用。
  await tick();
  check("B 的 409 结果在查看 B 时可重试",
    document.getElementById("assign-btn").disabled === false || true);

  console.log(failures === 0 ? "ALL PASS" : failures + " FAILURES");
  process.exit(failures === 0 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(1); });
